const d = (slug, title, task, solution, hint, given = '') => ({ kind: 'drill', slug, title, task, solution, hint, given });
const M = (body) => `public class Main {\n    public static void main(String[] args) {\n${body}\n    }\n}\n`;
const A = (body) => `import java.util.Arrays;\n\npublic class Main {\n    public static void main(String[] args) {\n${body}\n    }\n}\n`;
const U = (body, imports) =>
  imports.map((i) => `import java.util.${i};`).join('\n') +
  `\n\npublic class Main {\n    public static void main(String[] args) {\n${body}\n    }\n}\n`;

